SELECT COUNT(*) AS total_orders, SUM(CASE WHEN ORDER_STATUS = 'Cancelled' THEN 1 ELSE 0 END) AS cancelled_orders, SUM(CASE WHEN ORDER_STATUS = 'Delivered' THEN 1 ELSE 0 END) AS delivered_orders, AVG(CASE WHEN ORDER_STATUS = 'Delivered' THEN DELIVERY_TIME_MIN::FLOAT ELSE NULL END) AS avg_delivery_time_delivered, SUM(CASE WHEN ORDER_STATUS = 'Cancelled' THEN 1 ELSE 0 END) / COUNT(*)::FLOAT AS cancellation_rate
FROM ZOMATO_DLR.SOURCES.ORDERS
WHERE ORDER_DATE >= '2025-01-01' AND ORDER_DATE < '2026-01-01';
